mapper.select:
SELECT COUNT(*) 
FROM subscribe 
WHERE su_me_num = #{me_num} 
AND su_cl_num = #{cl_num}
AND su_status = 'regular'

SELECT SU_STATUS
FROM subscribe
WHERE SU_ME_NUM = #{me_num}
  AND SU_CL_NUM = #{cl_num}
  AND SU_STATUS = 'regular'

mapper.update:
CREATE EVENT delete_subscribe_event_${me_num}_${cl_num}
ON SCHEDULE AT ADDDATE(NOW(), INTERVAL 1 MONTH)
ON COMPLETION NOT PRESERVE
DO
BEGIN
    UPDATE subscribe
    SET SU_STATUS = 'normal'
    WHERE SU_ME_NUM = #{me_num}
      AND SU_CL_NUM = #{cl_num}
      AND SU_STATUS = 'regular'
      AND SU_DATE < NOW() - INTERVAL 30 DAY;
END;

UPDATE subscribe
SET SU_STATUS = 'regular',
    SU_DATE = NOW()
WHERE SU_ME_NUM = #{me_num}
  AND SU_CL_NUM = #{cl_num}

mapper.delete:
DELETE FROM subscribe 
WHERE SU_ME_NUM = #{me_num} 
  AND SU_CL_NUM = #{cl_num}
